import dayjs from 'dayjs';
import type { Dayjs } from 'dayjs';
import { DEFAULT_DATETIME_FORMAT, DEFAULT_FILENAME_FORMAT } from '../constants';

// 声明ExtPay全局变量
declare const ExtPay: any;

const DOWNLOAD_DELAY = 100;

// 初始化ExtPay实例
let globalExtPay: any;
try {
    globalExtPay = ExtPay('ig-download');
    console.log('ExtPay initialized successfully in content script');
} catch (error) {
    console.error('Failed to initialize ExtPay in content script:', error);
}

export function openInNewTab(url: string) {
   try {
      chrome.runtime.sendMessage({ type: 'open_url', data: url });
   } catch {
      window.open(url, '_blank', 'noopener,noreferrer');
   }
}

async function forceDownload(blob: string, filename: string, extension: string) {
   const { setting_format_replace_jpeg_with_jpg } = await chrome.storage.sync.get(['setting_format_replace_jpeg_with_jpg']);
   if (setting_format_replace_jpeg_with_jpg) {
      extension = extension.replace('jpeg', 'jpg');
   }
   const a = document.createElement('a');
   a.download = filename + '.' + extension;
   a.href = blob;
   document.body.appendChild(a);
   a.click();
   a.remove();
}

export function getMediaName(url: string) {
   const name = url.split('?')[0].split('/').pop();
   return name ? name.substring(0, name.lastIndexOf('.')) : url;
}

function showUpgradeAlert(downloadCount?: number) {
   const alertDiv = document.createElement('div');
   const countText = downloadCount ? chrome.i18n.getMessage("downloadLimitUsedMsg", [downloadCount.toString()]) : chrome.i18n.getMessage("downloadLimitReachedMsg");
   
   alertDiv.innerHTML = `
      <div style="
         position: fixed;
         top: 50%;
         left: 50%;
         transform: translate(-50%, -50%);
         background: white;
         border: 2px solid #e1306c;
         border-radius: 12px;
         padding: 24px;
         box-shadow: 0 8px 32px rgba(0,0,0,0.3);
         z-index: 10000;
         max-width: 400px;
         text-align: center;
         font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      ">
         <h3 style="margin: 0 0 16px 0; color: #262626; font-size: 18px;">${chrome.i18n.getMessage("downloadLimitReachedTitle")}</h3>
      <p style="margin: 0 0 20px 0; color: #8e8e8e; line-height: 1.4;">${countText} ${chrome.i18n.getMessage("upgradeToPremiumMsg")}</p>
         <div style="display: flex; gap: 12px; justify-content: center;">
            <button id="upgrade-btn" style="
               background: #e1306c;
               color: white;
               border: none;
               padding: 10px 20px;
               border-radius: 6px;
               cursor: pointer;
               font-weight: 600;
            ">${chrome.i18n.getMessage("upgradeBtnText")}</button>
            <button id="close-alert" style="
               background: #f5f5f5;
               color: #262626;
               border: none;
               padding: 10px 20px;
               border-radius: 6px;
               cursor: pointer;
            ">${chrome.i18n.getMessage("closeBtnText")}</button>
         </div>
      </div>
      <div style="
         position: fixed;
         top: 0;
         left: 0;
         width: 100%;
         height: 100%;
         background: rgba(0,0,0,0.5);
         z-index: 9999;
      "></div>
   `;
   
   document.body.appendChild(alertDiv);
   
   // 添加事件监听器
   const upgradeBtn = alertDiv.querySelector('#upgrade-btn');
   const closeBtn = alertDiv.querySelector('#close-alert');
   
   upgradeBtn?.addEventListener('click', () => {
        console.log('Upgrade button clicked');
        // 打开ExtPay支付页面
        if (globalExtPay) {
            try {
                console.log('Opening ExtPay payment page...');
                globalExtPay.openPaymentPage();
                // 关闭弹窗
                if (document.body.contains(alertDiv)) {
                    document.body.removeChild(alertDiv);
                }
            } catch (error) {
                console.error('Failed to open payment page:', error);
                // 备用方案：通过background script打开
                try {
                    chrome.runtime.sendMessage({ type: 'open-payment-page' });
                    if (document.body.contains(alertDiv)) {
                        document.body.removeChild(alertDiv);
                    }
                } catch (bgError) {
                    console.error('Background script error:', bgError);
                    document.body.removeChild(alertDiv);
                }
            }
        } else {
            console.error('ExtPay not available');
            // 备用方案：通过background script打开
            try {
                chrome.runtime.sendMessage({ type: 'open-payment-page' });
                if (document.body.contains(alertDiv)) {
                    document.body.removeChild(alertDiv);
                }
            } catch (error) {
                console.error('Error opening payment page:', error);
                document.body.removeChild(alertDiv);
            }
        }
    });
   
   closeBtn?.addEventListener('click', () => {
      document.body.removeChild(alertDiv);
   });
   
   // 点击背景关闭
   alertDiv.addEventListener('click', (e) => {
      if (e.target === alertDiv || (e.target as HTMLElement).style.position === 'fixed') {
         document.body.removeChild(alertDiv);
      }
   });
}

export interface DownloadParams {
   url: string;
   username?: string;
   datetime?: string | null | Dayjs;
   fileId?: string;
}

function hashCode(str: string) {
   let hash = 0;
   for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = (hash << 5) - hash + char;
      hash = hash & hash;
   }
   return hash >>> 0;
}

export async function checkDownloadPermission(): Promise<{ allowed: boolean; isPaid: boolean; downloadCount?: number }> {
    return new Promise((resolve) => {
        // 使用全局ExtPay实例
        if (!globalExtPay) {
            console.warn('Global ExtPay not available, allowing download');
            resolve({ allowed: true, isPaid: false });
            return;
        }
        
        console.log('Checking user payment status...');
        
        // 设置超时，防止ExtPay挂起
        const timeoutId = setTimeout(() => {
            console.warn('ExtPay getUser timed out, allowing download');
            resolve({ allowed: true, isPaid: false });
        }, 3000);
        
        globalExtPay.getUser().then((user: any) => {
            clearTimeout(timeoutId);
            
            console.log('User payment status retrieved:', user);
            
            if (user.paid) {
                // 付费用户直接允许下载
                console.log('User is paid, allowing download');
                resolve({ allowed: true, isPaid: true });
                return;
            }
            
            console.log('User is not paid, checking download count');
            
            // 检查本地存储中的下载计数
            chrome.storage.local.get(['downloadCount', 'lastResetDate'], (result) => {
                const today = new Date().toDateString();
                let downloadCount = result.downloadCount || 0;
                
                // 如果是新的一天，重置计数
                if (result.lastResetDate !== today) {
                    downloadCount = 0;
                    chrome.storage.local.set({ downloadCount: 0, lastResetDate: today });
                }
                
                console.log('Current download count:', downloadCount);
                
                if (downloadCount < 5) {
                    resolve({ allowed: true, isPaid: false, downloadCount });
                } else {
                    // 超过免费下载限制
                    console.log('Download limit reached');
                    resolve({ allowed: false, isPaid: false, downloadCount });
                }
            });
        }).catch((err: any) => {
            clearTimeout(timeoutId);
            console.error('ExtPay getUser error:', err);
            // 在出错的情况下允许下载
            resolve({ allowed: true, isPaid: false });
        });
    });
}

// 确保样式只注入一次
export function ensureSpinnerStyles() {
   if (!document.querySelector('#download-spinner-style')) {
      const style = document.createElement('style');
      style.id = 'download-spinner-style';
      style.textContent = `
         .spinner-loader {
            width: 16px;
            height: 16px;
            border: 2px solid rgba(255, 255, 255, 0.3);
            border-top: 2px solid currentColor;
            border-radius: 50%;
            animation: spinnerRotate 1s linear infinite;
         }
         
         @keyframes spinnerRotate {
            0% {
               transform: rotate(0deg);
            }
            100% {
               transform: rotate(360deg);
            }
         }
      `;
      document.head.appendChild(style);
   }
}

// 添加下载状态管理函数
export function setDownloadButtonState(button: HTMLElement, state: 'downloading' | 'completed' | 'normal') {
   switch (state) {
      case 'downloading':
         // 立即设置视觉状态
         button.classList.add('downloading');
         button.style.setProperty('opacity', '0.8');
         button.style.setProperty('filter', 'drop-shadow(0px 0px 8px orange)');
         button.style.setProperty('cursor', 'wait');
         button.setAttribute('title', 'Downloading...');
         
         // 立即替换按钮内容
         const originalContent = button.innerHTML;
         button.setAttribute('data-original-content', originalContent);
         button.innerHTML = `
            <div style="display: flex; align-items: center; justify-content: center;">
               <div class="spinner-loader"></div>
            </div>
         `;
         break;
      case 'completed':
         button.classList.remove('downloading');
         // 恢复原始内容
         const completedOriginalContent = button.getAttribute('data-original-content');
         if (completedOriginalContent) {
            button.innerHTML = completedOriginalContent;
            button.removeAttribute('data-original-content');
         }
         button.style.setProperty('filter', 'drop-shadow(0px 0px 8px green)');
         button.setAttribute('title', 'Download completed!');
         setTimeout(() => {
            setDownloadButtonState(button, 'normal');
         }, 2000);
         break;
      case 'normal':
         button.classList.remove('downloading');
         // 恢复原始内容
         const normalOriginalContent = button.getAttribute('data-original-content');
         if (normalOriginalContent) {
            button.innerHTML = normalOriginalContent;
            button.removeAttribute('data-original-content');
         }
         button.style.removeProperty('opacity');
         button.style.removeProperty('filter');
         button.style.removeProperty('cursor');
         button.setAttribute('title', 'Download');
         break;
   }
}

export async function downloadResource({ url, username, datetime, fileId, button }: DownloadParams & { button?: HTMLElement }) {
   console.log(`Downloading ${url}`);

   // 使用传入的按钮元素，或者查找最近点击的下载按钮
   let downloadButton = button;
   if (!downloadButton) {
      // 查找所有可能的下载按钮类名
      downloadButton = document.querySelector('.custom-btn.download-btn') as HTMLElement ||
                      document.querySelector('.custom-btn') as HTMLElement ||
                      document.querySelector('[title="Download"]') as HTMLElement;
   }
   
   // 如果按钮还没有设置为下载状态，则设置（兼容直接调用的情况）
   if (downloadButton && !downloadButton.classList.contains('downloading')) {
      ensureSpinnerStyles();
      setDownloadButtonState(downloadButton, 'downloading');
   }

   // 检查下载权限
   try {
      const response = await checkDownloadPermission();
      if (!response.allowed) {
            // 显示付费提示
            if (downloadButton) {
               setDownloadButtonState(downloadButton, 'normal');
            }
            showUpgradeAlert(response.downloadCount);
            return;
        }
      
      // 如果是免费用户，增加下载计数
        if (!response.isPaid) {
            const result = await chrome.storage.local.get(['downloadCount', 'lastResetDate']);
            const today = new Date().toDateString();
            let downloadCount = result.downloadCount || 0;
            
            // 如果是新的一天，重置计数
            if (result.lastResetDate !== today) {
                downloadCount = 0;
            }
            
            downloadCount += 1;
            await chrome.storage.local.set({ downloadCount, lastResetDate: today });
            console.log(`Download count incremented to: ${downloadCount}`);
            
            // 如果下载次数接近限制，显示警告
            if (downloadCount >= 3 && downloadCount < 5) {
                const remainingDownloads = 5 - downloadCount;
                console.log(`Warning: ${remainingDownloads} free downloads remaining`);
            }
        }
      
      if (!response.isPaid && response.downloadCount) {
         console.log(`Free downloads used: ${response.downloadCount}/5`);
      }
   } catch (error) {
      console.error('Error checking download permission:', error);
      // 出错时继续下载
   }

   const {
      setting_format_datetime = DEFAULT_DATETIME_FORMAT,
      setting_format_filename = DEFAULT_FILENAME_FORMAT,
      setting_format_use_hash_id,
   } = await chrome.storage.sync.get(['setting_format_datetime', 'setting_format_filename', 'setting_format_use_hash_id']);
   
   // When setting_format_use_hash_id is true, we will hash the fileId. The mediaIndex will be meaningless. 
   if (setting_format_use_hash_id && fileId) {
      fileId = hashCode(fileId).toString();
   }

   let filename = fileId;

   if (username && datetime && fileId) {
      console.log(`username: ${username}, datetime: ${datetime}, fileId: ${fileId}`);
      datetime = dayjs(datetime).format(setting_format_datetime);

      filename = setting_format_filename
         .replace(/{username}/g, username)
         .replace(/{datetime}/g, datetime)
         .replace(/{id}/g, fileId);
   }

   if (!filename) {
      filename = getMediaName(url);
   }
   if (url.startsWith('blob:')) {
      forceDownload(url, filename, 'mp4');
      
      // 显示下载完成状态
      if (downloadButton) {
         setDownloadButtonState(downloadButton, 'completed');
      }
      
      // 下载完成后增加计数
      chrome.runtime.sendMessage({ type: 'increment_download_count' })
         .then((response) => {
            if (response && response.success) {
               console.log('Download count incremented:', response.downloadCount);
            }
         })
         .catch((error) => {
            console.error('Error incrementing download count:', error);
         });
      return;
   }
   fetch(url, {
      headers: new Headers({
         Origin: location.origin,
      }),
      mode: 'cors',
   })
      .then((response) => response.blob())
      .then((blob) => {
         const extension = blob.type.split('/').pop();
         const blobUrl = window.URL.createObjectURL(blob);
         forceDownload(blobUrl, filename, extension || 'jpg');
         
         // 显示下载完成状态
         if (downloadButton) {
            setDownloadButtonState(downloadButton, 'completed');
         }
         
         // 下载完成后增加计数
         chrome.runtime.sendMessage({ type: 'increment_download_count' })
            .then((response) => {
               if (response && response.success) {
                  console.log('Download count incremented:', response.downloadCount);
               }
            })
            .catch((error) => {
               console.error('Error incrementing download count:', error);
            });
      })
      .catch((e) => {
         console.error(e);
         // 下载失败时恢复按钮状态
         if (downloadButton) {
            setDownloadButtonState(downloadButton, 'normal');
         }
      });
}

const mediaInfoCache: Map<string, any> = new Map(); // key: media id, value: info json
const mediaIdCache: Map<string, string> = new Map(); // key: post id, value: media id

const findAppId = () => {
   const appIdPattern = /"X-IG-App-ID":"([\d]+)"/;
   const bodyScripts: NodeListOf<HTMLScriptElement> = document.querySelectorAll('body > script');
   for (let i = 0; i < bodyScripts.length; ++i) {
      const match = bodyScripts[i].text.match(appIdPattern);
      if (match) return match[1];
   }
   console.log('Cannot find app id');
   return null;
};

function findPostId(articleNode: HTMLElement) {
   const pathname = window.location.pathname;
   if (pathname.startsWith('/reels/')) {
      return pathname.split('/')[2];
   } else if (pathname.startsWith('/stories/')) {
      return pathname.split('/')[3];
   } else if (pathname.startsWith('/reel/')) {
      return pathname.split('/')[2];
   }
   // Fallback: handle paths like /{username}/p/{id}/ where /p/ is not at pathname start
   if (pathname.includes('/p/')) {
      const matchFromPath = pathname.match(/\/p\/([^/]+)/);
      if (matchFromPath) return matchFromPath[1];
   }
   const postIdPattern = /^\/p\/([^/]+)\//;
   const aNodes = articleNode.querySelectorAll('a');
   for (let i = 0; i < aNodes.length; ++i) {
      const link = aNodes[i].getAttribute('href');
      if (link) {
         const match = link.match(postIdPattern);
         if (match) return match[1];
      }
   }
   return null;
}

const findMediaId = async (postId: string) => {
   const mediaIdPattern = /instagram:\/\/media\?id=(\d+)|["' ]media_id["' ]:["' ](\d+)["' ]/;
   const match = window.location.href.match(/www.instagram.com\/stories\/[^/]+\/(\d+)/);
   if (match) return match[1];
   if (!mediaIdCache.has(postId)) {
      const postUrl = `https://www.instagram.com/p/${postId}/`;
      const resp = await fetch(postUrl);
      const text = await resp.text();
      const idMatch = text.match(mediaIdPattern);
      if (!idMatch) return null;
      let mediaId = null;
      for (let i = 0; i < idMatch.length; ++i) {
         if (idMatch[i]) mediaId = idMatch[i];
      }
      if (!mediaId) return null;
      mediaIdCache.set(postId, mediaId);
   }
   return mediaIdCache.get(postId);
};

const getImgOrVideoUrl = (item: Record<string, any>) => {
   if ('video_versions' in item) {
      return item.video_versions[0].url;
   } else {
      return item.image_versions2.candidates[0].url;
   }
};

export const getUrlFromInfoApi = async (articleNode: HTMLElement, mediaIdx = 0): Promise<Record<string, any> | null> => {
   try {
      const appId = findAppId();
      if (!appId) {
         console.log('Cannot find appid');
         return null;
      }
      const postId = findPostId(articleNode);
      if (!postId) {
         console.log('Cannot find post id');
         return null;
      }
      const mediaId = await findMediaId(postId);
      if (!mediaId) {
         console.log('Cannot find media id');
         return null;
      }
      if (!mediaInfoCache.has(mediaId)) {
         const url = 'https://i.instagram.com/api/v1/media/' + mediaId + '/info/';
         const resp = await fetch(url, {
            method: 'GET',
            headers: {
               Accept: '*/*',
               'X-IG-App-ID': appId,
            },
            credentials: 'include',
            mode: 'cors',
         });

         if (resp.status !== 200) {
            console.log(`Fetch info API failed with status code: ${resp.status}`);
            return null;
         }
         const respJson = await resp.json();
         mediaInfoCache.set(mediaId, respJson);
      }
      const infoJson = mediaInfoCache.get(mediaId);
      const data = infoJson.items[0];
      if ('carousel_media' in data) {
         // multi-media post
         const item = data.carousel_media[Math.max(mediaIdx, 0)];
         return {
            ...item,
            url: getImgOrVideoUrl(item),
            taken_at: data.taken_at,
            owner: item.owner?.username || data.owner.username,
            coauthor_producers: data.coauthor_producers?.map((i: any) => i.username) || [],
            origin_data: data,
         };
      } else {
         // single media post
         return {
            ...data,
            url: getImgOrVideoUrl(data),
            owner: data.owner.username,
            coauthor_producers: data.coauthor_producers?.map((i: any) => i.username) || [],
         };
      }
   } catch (e: any) {
      console.log(`Uncaught in getUrlFromInfoApi(): ${e}\n${e.stack}`);
      return null;
   }
};

function adjustVideoButton(btns: NodeListOf<Element>) {
   btns.forEach((i) => {
      const btn = i.parentNode?.parentNode?.parentNode?.parentNode;
      if (btn instanceof HTMLElement) {
         btn.style.zIndex = '999';
         btn.style.bottom = '3rem';
      }
   });
}

export function getParentArticleNode(node: HTMLElement | null) {
   if (node === null) return null;
   if (node.tagName === 'ARTICLE') {
      return node;
   }
   return getParentArticleNode(node.parentElement);
}

export function getParentSectionNode(node: HTMLElement | null) {
   if (node === null) return null;
   if (node.tagName === 'SECTION') {
      return node;
   }
   return getParentSectionNode(node.parentElement);
}

export async function handleVideo() {
   const { setting_enable_video_controls } = await chrome.storage.sync.get(['setting_enable_video_controls']);
   if (!setting_enable_video_controls) return;
   const videos = document.querySelectorAll('video');
   for (let i = 0; i < videos.length; i++) {
      if (videos[i].controls === true) continue;
      videos[i].style.zIndex = '1';
      videos[i].style.position = 'relative';
      videos[i].controls = true;
      videos[i].onvolumechange = () => {
         const isMutingBtn = videos[i].parentElement?.querySelector(
            'path[d="M1.5 13.3c-.8 0-1.5.7-1.5 1.5v18.4c0 .8.7 1.5 1.5 1.5h8.7l12.9 12.9c.9.9 2.5.3 2.5-1v-9.8c0-.4-.2-.8-.4-1.1l-22-22c-.3-.3-.7-.4-1.1-.4h-.6zm46.8 31.4-5.5-5.5C44.9 36.6 48 31.4 48 24c0-11.4-7.2-17.4-7.2-17.4-.6-.6-1.6-.6-2.2 0L37.2 8c-.6.6-.6 1.6 0 2.2 0 0 5.7 5 5.7 13.8 0 5.4-2.1 9.3-3.8 11.6L35.5 32c1.1-1.7 2.3-4.4 2.3-8 0-6.8-4.1-10.3-4.1-10.3-.6-.6-1.6-.6-2.2 0l-1.4 1.4c-.6.6-.6 1.6 0 2.2 0 0 2.6 2 2.6 6.7 0 1.8-.4 3.2-.9 4.3L25.5 22V1.4c0-1.3-1.6-1.9-2.5-1L13.5 10 3.3-.3c-.6-.6-1.5-.6-2.1 0L-.2 1.1c-.6.6-.6 1.5 0 2.1L4 7.6l26.8 26.8 13.9 13.9c.6.6 1.5.6 2.1 0l1.4-1.4c.7-.6.7-1.6.1-2.2z"]'
         );
         const isUnmutingBtn = videos[i].parentElement?.querySelector(
            'path[d="M16.636 7.028a1.5 1.5 0 1 0-2.395 1.807 5.365 5.365 0 0 1 1.103 3.17 5.378 5.378 0 0 1-1.105 3.176 1.5 1.5 0 1 0 2.395 1.806 8.396 8.396 0 0 0 1.71-4.981 8.39 8.39 0 0 0-1.708-4.978Zm3.73-2.332A1.5 1.5 0 1 0 18.04 6.59 8.823 8.823 0 0 1 20 12.007a8.798 8.798 0 0 1-1.96 5.415 1.5 1.5 0 0 0 2.326 1.894 11.672 11.672 0 0 0 2.635-7.31 11.682 11.682 0 0 0-2.635-7.31Zm-8.963-3.613a1.001 1.001 0 0 0-1.082.187L5.265 6H2a1 1 0 0 0-1 1v10.003a1 1 0 0 0 1 1h3.265l5.01 4.682.02.021a1 1 0 0 0 1.704-.814L12.005 2a1 1 0 0 0-.602-.917Z"]'
         );
         if (videos[i].muted === false && isMutingBtn) {
            isMutingBtn.parentElement?.parentElement?.parentElement?.click();
         }
         if (videos[i].muted === true && isUnmutingBtn) {
            isUnmutingBtn.parentElement?.parentElement?.parentElement?.click();
         }
      };
      const btns = videos[i].parentNode?.querySelectorAll('button svg path');
      if (btns) {
         adjustVideoButton(btns);
      }
   }
}

export const checkType = () => {
   if (navigator && navigator.userAgent && /Mobi|Android|iPhone/i.test(navigator.userAgent)) {
      if (navigator && navigator.userAgent && /(iPhone|iPad|iPod|iOS)/i.test(navigator.userAgent)) {
         return 'ios';
      } else {
         return 'android';
      }
   } else {
      return 'pc';
   }
};

export async function fetchHtml() {
   const resp = await fetch(window.location.href, {
      referrerPolicy: 'no-referrer',
   });
   const content = await resp.text();
   const parser = new DOMParser();
   const doc = parser.parseFromString(content, 'text/html');
   return doc.querySelectorAll('script');
}
